PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS app_schema_versions (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
INSERT INTO app_schema_versions (version, applied_at) VALUES (1, strftime('%Y-%m-%dT%H:%M:%fZ','now'));
CREATE TABLE IF NOT EXISTS households (id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
INSERT INTO households (id, name, created_at, updated_at) VALUES ('00000000-0000-0000-0000-000000000001', 'Local household', strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'));

CREATE TABLE IF NOT EXISTS household_members (id TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(id), name TEXT NOT NULL, role TEXT NOT NULL, notes TEXT NOT NULL, confidence TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS categories (id TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(id), name TEXT NOT NULL, kind TEXT NOT NULL, notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS bank_accounts (id TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(id), name TEXT NOT NULL, institution TEXT NOT NULL, account_type TEXT NOT NULL, last_four TEXT, balance_cents INTEGER, notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK(balance_cents IS NULL OR balance_cents >= 0));
CREATE TABLE IF NOT EXISTS income_sources (id TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(id), member_id TEXT REFERENCES household_members(id), name TEXT NOT NULL, amount_cents INTEGER, frequency TEXT NOT NULL, kind TEXT NOT NULL, hourly_rate_cents INTEGER, active INTEGER NOT NULL, notes TEXT NOT NULL, confidence TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK(amount_cents IS NULL OR amount_cents >= 0));
CREATE TABLE IF NOT EXISTS income_transactions (id TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(id), source_id TEXT REFERENCES income_sources(id), bank_account_id TEXT REFERENCES bank_accounts(id), name TEXT NOT NULL, amount_cents INTEGER NOT NULL, date TEXT NOT NULL, notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK(amount_cents >= 0));
CREATE TABLE IF NOT EXISTS expenses (id TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(id), category_id TEXT REFERENCES categories(id), name TEXT NOT NULL, amount_cents INTEGER, frequency TEXT NOT NULL, category TEXT NOT NULL, due_day INTEGER, active INTEGER NOT NULL, priority INTEGER NOT NULL, notes TEXT NOT NULL, confidence TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK(amount_cents IS NULL OR amount_cents >= 0));
CREATE TABLE IF NOT EXISTS expense_transactions (id TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(id), expense_id TEXT REFERENCES expenses(id), bank_account_id TEXT REFERENCES bank_accounts(id), name TEXT NOT NULL, amount_cents INTEGER, date TEXT NOT NULL, category TEXT NOT NULL, kind TEXT NOT NULL, cash_outflow INTEGER NOT NULL DEFAULT 1, notes TEXT NOT NULL, confidence TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK(amount_cents IS NULL OR amount_cents >= 0));
CREATE TABLE IF NOT EXISTS debts (id TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(id), owner_id TEXT REFERENCES household_members(id), original_debt_id TEXT REFERENCES debts(id), name TEXT NOT NULL, creditor TEXT NOT NULL, owner_type TEXT NOT NULL, original_balance_cents INTEGER, balance_cents INTEGER, apr REAL, minimum_payment_cents INTEGER, status TEXT NOT NULL, due_date TEXT, days_late INTEGER, security TEXT NOT NULL, settlement_offer_cents INTEGER, collection_agency TEXT NOT NULL, priority INTEGER NOT NULL, active INTEGER NOT NULL, history_json TEXT NOT NULL, fees_cents INTEGER, court_ordered INTEGER NOT NULL, transportation_risk INTEGER NOT NULL, active_at_risk INTEGER NOT NULL, credit_utilization REAL, user_urgency INTEGER NOT NULL, priority_override TEXT, priority_explanation TEXT NOT NULL, charge_off INTEGER NOT NULL, notes TEXT NOT NULL, confidence TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK(balance_cents IS NULL OR balance_cents >= 0));
CREATE TABLE IF NOT EXISTS settlement_offers (id TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(id), debt_id TEXT NOT NULL REFERENCES debts(id), name TEXT NOT NULL, offer_amount_cents INTEGER, offer_percent REAL, agreed_amount_cents INTEGER, paid_amount_cents INTEGER, status TEXT NOT NULL, date TEXT, plan_type TEXT NOT NULL, down_payment_cents INTEGER, installments INTEGER NOT NULL, first_due_date TEXT, offer_expiration TEXT, written_agreement INTEGER NOT NULL, notes TEXT NOT NULL, confidence TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK(offer_amount_cents IS NULL OR offer_amount_cents >= 0));
CREATE TABLE IF NOT EXISTS debt_payments (id TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(id), debt_id TEXT REFERENCES debts(id), expense_id TEXT REFERENCES expenses(id), name TEXT NOT NULL, date TEXT NOT NULL, amount_cents INTEGER NOT NULL, kind TEXT NOT NULL, cash_outflow INTEGER NOT NULL, notes TEXT NOT NULL, confidence TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK(amount_cents >= 0));
CREATE TABLE IF NOT EXISTS settlement_payments (id TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(id), debt_id TEXT REFERENCES debts(id), settlement_id TEXT NOT NULL REFERENCES settlement_offers(id), expense_id TEXT REFERENCES expenses(id), name TEXT NOT NULL, date TEXT NOT NULL, amount_cents INTEGER NOT NULL, kind TEXT NOT NULL, cash_outflow INTEGER NOT NULL, notes TEXT NOT NULL, confidence TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK(amount_cents >= 0));
CREATE TABLE IF NOT EXISTS savings_goals (id TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(id), name TEXT NOT NULL, target_cents INTEGER, saved_cents INTEGER, monthly_contribution_cents INTEGER, kind TEXT NOT NULL, target_date TEXT, notes TEXT NOT NULL, confidence TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS trading_accounts (id TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(id), name TEXT NOT NULL, platform TEXT NOT NULL, funded_balance_cents INTEGER, realized_profit_cents INTEGER, actual_payout_cents INTEGER, fees_cents INTEGER, tax_reserve_cents INTEGER, drawdown_cents INTEGER, projected_payout_cents INTEGER, notes TEXT NOT NULL, confidence TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS trading_transactions (id TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(id), trading_id TEXT NOT NULL REFERENCES trading_accounts(id), name TEXT NOT NULL, amount_cents INTEGER NOT NULL, date TEXT NOT NULL, kind TEXT NOT NULL, notes TEXT NOT NULL, confidence TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK(amount_cents >= 0));
CREATE TABLE IF NOT EXISTS monthly_budgets (id TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(id), category_id TEXT REFERENCES categories(id), name TEXT NOT NULL, month TEXT NOT NULL, planned_cents INTEGER NOT NULL, actual_cents INTEGER, notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS application_settings (id TEXT PRIMARY KEY, household_id TEXT NOT NULL REFERENCES households(id), theme TEXT NOT NULL, monthly_essentials_buffer_cents INTEGER NOT NULL, home_credit_milestone INTEGER, starting_cash_cents INTEGER NOT NULL, monthly_emergency_savings_cents INTEGER NOT NULL, monthly_extra_debt_payment_cents INTEGER NOT NULL, updated_at TEXT NOT NULL);

CREATE INDEX IF NOT EXISTS idx_members_household ON household_members(household_id);
CREATE INDEX IF NOT EXISTS idx_income_sources_member ON income_sources(member_id);
CREATE INDEX IF NOT EXISTS idx_income_transactions_date ON income_transactions(date);
CREATE INDEX IF NOT EXISTS idx_expenses_household ON expenses(household_id);
CREATE INDEX IF NOT EXISTS idx_expense_transactions_date ON expense_transactions(date);
CREATE INDEX IF NOT EXISTS idx_debts_owner ON debts(owner_id);
CREATE INDEX IF NOT EXISTS idx_debts_original ON debts(original_debt_id);
CREATE INDEX IF NOT EXISTS idx_debts_status ON debts(status);
CREATE INDEX IF NOT EXISTS idx_settlement_offers_debt ON settlement_offers(debt_id);
CREATE INDEX IF NOT EXISTS idx_debt_payments_debt_date ON debt_payments(debt_id, date);
CREATE INDEX IF NOT EXISTS idx_settlement_payments_offer_date ON settlement_payments(settlement_id, date);
CREATE INDEX IF NOT EXISTS idx_trading_transactions_account_date ON trading_transactions(trading_id, date);
CREATE INDEX IF NOT EXISTS idx_monthly_budgets_month ON monthly_budgets(month);
